// Writes quote.json: a quote signed the way the backend signs it on the NEAR rail.
//
//   node contracts-near/settlement/tests/fixtures/make_quote.mjs
//
// TEST ONLY. The keys below are the public RFC 8032 Ed25519 test vectors (section 7.1,
// tests 1 and 2). Everyone knows their secret seeds: never use them for real funds.
//
// Signing rule (the contract checks exactly this):
//   quoteJson = JSON.stringify(quote)                       // any key order, no reformatting after
//   signature = ed25519(utf8(quoteJson))                    // raw bytes, no hashing, no prefix
//   msg       = JSON.stringify({ quote: quoteJson, signature: base64(signature) })
// msg is the `msg` argument of `ft_transfer_call` on the token, with the settlement
// contract as `receiver_id` and `amount` equal to `token_amount`.

import { createHash, createPrivateKey, createPublicKey, sign, verify } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// RFC 8032 7.1 TEST 1: the quote signer (the backend's key in production).
const QUOTE_SIGNER_SEED_HEX = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60';
// RFC 8032 7.1 TEST 2: the payer. Its implicit account id is the hex of its public key.
const PAYER_SEED_HEX = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb';

const TOKEN = 'test-usdc.testnet';
const SETTLEMENT = 'settlement.testnet';
// The unit tests set the block time to NOW_MS; the quote lives 60 s.
const NOW_MS = 1_800_000_000_000;

const PKCS8_ED25519_PREFIX = Buffer.from('302e020100300506032b657004220420', 'hex');

function keyPair(seedHex) {
  const privateKey = createPrivateKey({
    key: Buffer.concat([PKCS8_ED25519_PREFIX, Buffer.from(seedHex, 'hex')]),
    format: 'der',
    type: 'pkcs8',
  });
  const spki = createPublicKey(privateKey).export({ format: 'der', type: 'spki' });
  return { privateKey, publicKey: createPublicKey(privateKey), publicKeyBytes: spki.subarray(spki.length - 32) };
}

const BASE58_ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function base58(bytes) {
  let n = BigInt('0x' + (Buffer.from(bytes).toString('hex') || '0'));
  let out = '';
  while (n > 0n) {
    out = BASE58_ALPHABET[Number(n % 58n)] + out;
    n /= 58n;
  }
  for (const b of bytes) {
    if (b !== 0) break;
    out = '1' + out;
  }
  return out;
}

const sha256Hex = (text) => createHash('sha256').update(text, 'utf8').digest('hex');

const signer = keyPair(QUOTE_SIGNER_SEED_HEX);
const payer = keyPair(PAYER_SEED_HEX);
const payerAccountId = payer.publicKeyBytes.toString('hex');

const quote = {
  quote_id: '0x' + sha256Hex('quote-1'),
  payer: payerAccountId,
  token: TOKEN,
  token_amount: '2850000', // 2.85 USDC (6 decimals)
  fiat_currency: 'THB',
  fiat_amount: '10000', // 100.00 THB in satang
  merchant_ref_hash: '0x' + sha256Hex('biller:099999999999901'),
  expires_at_ms: NOW_MS + 60_000,
};
const quoteJson = JSON.stringify(quote);
const signature = sign(null, Buffer.from(quoteJson, 'utf8'), signer.privateKey);
if (!verify(null, Buffer.from(quoteJson, 'utf8'), signer.publicKey, signature)) {
  throw new Error('signature does not verify');
}
const msg = JSON.stringify({ quote: quoteJson, signature: signature.toString('base64') });

const fixture = {
  _comment:
    'TEST ONLY. Keys are the public RFC 8032 Ed25519 test vectors; never use them for real funds. Generated by make_quote.mjs.',
  quote_signer: {
    seed_hex: QUOTE_SIGNER_SEED_HEX,
    public_key_hex: signer.publicKeyBytes.toString('hex'),
    public_key: 'ed25519:' + base58(signer.publicKeyBytes),
  },
  payer: {
    seed_hex: PAYER_SEED_HEX,
    public_key: 'ed25519:' + base58(payer.publicKeyBytes),
    account_id: payerAccountId,
  },
  token: TOKEN,
  settlement: SETTLEMENT,
  now_ms: NOW_MS,
  quote,
  quote_json: quoteJson,
  signature_base64: signature.toString('base64'),
  signature_hex: signature.toString('hex'),
  msg,
  ft_transfer_call_args: { receiver_id: SETTLEMENT, amount: quote.token_amount, msg },
};

const out = join(dirname(fileURLToPath(import.meta.url)), 'quote.json');
writeFileSync(out, JSON.stringify(fixture, null, 2) + '\n');
console.log('wrote', out);
